import React, { createContext, useContext, useState, useEffect } from 'react';
import { authApi, userApi } from '../services/api';

// Create auth context
const AuthContext = createContext();

// Auth provider component
export const AuthProvider = ({ children }) => {
  const [currentUser, setCurrentUser] = useState(null);
  const [loading, setLoading] = useState(true);
  const [isNewUser, setIsNewUser] = useState(false);
  const [onboardingCompleted, setOnboardingCompleted] = useState(false);
  const [allUsers, setAllUsers] = useState([]);

  // Load user from localStorage on initial render
  useEffect(() => {
    const storedUser = localStorage.getItem('user');
    const storedOnboarding = localStorage.getItem('onboardingCompleted');
    
    if (storedUser) {
      try {
        const parsedUser = JSON.parse(storedUser);
        
        // Ensure user has the required properties
        const userWithDefaults = {
          ...parsedUser,
          studyData: Array.isArray(parsedUser.studyData) ? parsedUser.studyData : [],
          tasks: Array.isArray(parsedUser.tasks) ? parsedUser.tasks : [],
          streakDays: typeof parsedUser.streakDays === 'number' ? parsedUser.streakDays : 0,
          gender: parsedUser.gender || 'neutral',
          customAvatar: parsedUser.customAvatar || null
        };
        
        setCurrentUser(userWithDefaults);
        
        // If we have a user, also load the leaderboard
        loadLeaderboard();
      } catch (error) {
        console.error('Error parsing stored user:', error);
        localStorage.removeItem('user'); // Clear invalid data
      }
    }
    
    if (storedOnboarding) {
      try {
        setOnboardingCompleted(JSON.parse(storedOnboarding));
      } catch (error) {
        console.error('Error parsing stored onboarding status:', error);
        localStorage.removeItem('onboardingCompleted'); // Clear invalid data
      }
    }
    
    setLoading(false);
  }, []);

  // Load leaderboard data from API
  const loadLeaderboard = async () => {
    try {
      const response = await userApi.getLeaderboard();
      if (response.success && Array.isArray(response.users)) {
        setAllUsers(response.users);
        return response.users;
      } else {
        console.error('Invalid leaderboard response:', response);
        setAllUsers([]);
        return [];
      }
    } catch (error) {
      console.error('Error loading leaderboard:', error);
      setAllUsers([]);
      return [];
    }
  };

  // Get leaderboard rankings
  const getLeaderboard = async (type = 'study') => {
    try {
      // Only refresh leaderboard data if it's empty
      if (!allUsers || allUsers.length === 0) {
        await loadLeaderboard();
      }
      
      let sortedUsers = [...allUsers];
      
      if (!Array.isArray(sortedUsers)) {
        console.error('Leaderboard data is not an array:', sortedUsers);
        return [];
      }
      
      // Ensure we have valid numeric values before sorting
      sortedUsers = sortedUsers.map(user => ({
        ...user,
        totalStudyHours: typeof user.totalStudyHours === 'number' ? user.totalStudyHours : 0,
        completedTasks: typeof user.completedTasks === 'number' ? user.completedTasks : 0,
        streakDays: typeof user.streakDays === 'number' ? user.streakDays : 0
      }));
      
      // Debug log before sorting
      console.log(`Pre-sort leaderboard data (${type}):`, sortedUsers.map(user => ({
        name: user.name,
        completedTasks: user.completedTasks,
        totalStudyHours: user.totalStudyHours,
        streakDays: user.streakDays
      })));
      
      // Implement stable sorting with consistent tie-breaking
      if (type === 'study') {
        // Sort by total study hours, then by name for stability
        sortedUsers = sortedUsers.sort((a, b) => {
          // Ensure numeric comparison
          const aHours = Number(a.totalStudyHours) || 0;
          const bHours = Number(b.totalStudyHours) || 0;
          
          const hoursDiff = bHours - aHours;
          return hoursDiff !== 0 ? hoursDiff : a.name.localeCompare(b.name);
        });
      } else if (type === 'tasks') {
        // Force numeric conversion and sort by completed tasks
        sortedUsers = sortedUsers.sort((a, b) => {
          // Ensure strict numeric comparison with explicit conversion
          const aTasks = parseInt(a.completedTasks, 10) || 0;
          const bTasks = parseInt(b.completedTasks, 10) || 0;
          
          // Log comparison values for debugging
          console.log(`Comparing tasks: ${a.name}(${aTasks}) vs ${b.name}(${bTasks})`);
          
          // Use strict numerical difference for sorting
          if (bTasks !== aTasks) {
            return bTasks - aTasks; // Descending order
          }
          
          // If tasks are equal, sort by name (alphabetically) for consistency
          return a.name.localeCompare(b.name);
        });
      } else if (type === 'streak') {
        // Sort by streak days, then by name for stability
        sortedUsers = sortedUsers.sort((a, b) => {
          // Ensure numeric comparison
          const aStreak = Number(a.streakDays) || 0;
          const bStreak = Number(b.streakDays) || 0;
          
          const streakDiff = bStreak - aStreak;
          return streakDiff !== 0 ? streakDiff : a.name.localeCompare(b.name);
        });
      }
      
      // Debug log after sorting
      console.log(`Post-sort leaderboard data (${type}):`, sortedUsers.map(user => ({
        name: user.name,
        completedTasks: user.completedTasks,
        totalStudyHours: user.totalStudyHours,
        streakDays: user.streakDays,
        rank: sortedUsers.indexOf(user) + 1
      })));
      
      // Add rank to each user
      return sortedUsers.map((user, index) => ({
        ...user,
        rank: index + 1
      }));
    } catch (error) {
      console.error('Error getting leaderboard:', error);
      return [];
    }
  };

  // Update user data function (for tasks, study data, etc.)
  const updateUserData = async (data) => {
    if (!currentUser) return false;
    
    try {
      const response = await userApi.updateProfile(currentUser._id, data);
      
      if (response.success) {
        const updatedUser = response.user;
        setCurrentUser(updatedUser);
        localStorage.setItem('user', JSON.stringify(updatedUser));
        return true;
      }
      
      return false;
    } catch (error) {
      console.error('Error updating user data:', error);
      return false;
    }
  };

  // Update user tasks specifically
  const updateTasks = async (tasks) => {
    if (!currentUser) return false;
    
    // Ensure tasks is always an array 
    const safeTasks = Array.isArray(tasks) ? tasks : [];
    
    try {
      const response = await userApi.updateTasks(currentUser._id, safeTasks);
      
      if (response.success) {
        const updatedUser = response.user;
        setCurrentUser(updatedUser);
        localStorage.setItem('user', JSON.stringify(updatedUser));
        return true;
      }
      
      return false;
    } catch (error) {
      console.error('Error updating tasks:', error);
      return false;
    }
  };

  // Update streak days specifically
  const updateStreak = async (streakDays) => {
    if (!currentUser) return false;
    
    // Ensure streakDays is a number
    const safeStreak = typeof streakDays === 'number' ? streakDays : 0;
    
    try {
      const response = await userApi.updateStreak(currentUser._id, safeStreak);
      
      if (response.success) {
        const updatedUser = response.user;
        setCurrentUser(updatedUser);
        localStorage.setItem('user', JSON.stringify(updatedUser));
        return true;
      }
      
      return false;
    } catch (error) {
      console.error('Error updating streak:', error);
      return false;
    }
  };

  // Login function
  const login = async (userData) => {
    try {
      const response = await authApi.login(userData);
      
      if (response.success) {
        setCurrentUser(response.user);
        localStorage.setItem('user', JSON.stringify(response.user));
        
        // Load fresh leaderboard data
        await loadLeaderboard();
        
        if (response.requiresOnboarding) {
          setIsNewUser(true);
          return { success: true, requiresOnboarding: true };
        }
        
        return { success: true, requiresOnboarding: false };
      }
      
      return { success: false, message: response.message || 'Invalid login credentials' };
    } catch (error) {
      console.error('Login error:', error);
      return { success: false, message: error.message || 'Error during login' };
    }
  };

  // Signup function
  const signup = async (userData) => {
    try {
      const response = await authApi.register(userData);
      
      if (response.success) {
        setCurrentUser(response.user);
        localStorage.setItem('user', JSON.stringify(response.user));
        setIsNewUser(true);
        
        // Load fresh leaderboard data
        await loadLeaderboard();
        
        return { success: true, requiresOnboarding: true };
      }
      
      return { success: false, message: response.message || 'Error creating account' };
    } catch (error) {
      console.error('Signup error:', error);
      return { success: false, message: error.message || 'Error during signup' };
    }
  };

  // Complete onboarding function
  const completeOnboarding = async (userPreferences) => {
    if (!currentUser) return false;
    
    try {
      const response = await authApi.completeOnboarding(currentUser._id, userPreferences);
      
      if (response.success) {
        const updatedUser = response.user;
        setCurrentUser(updatedUser);
        localStorage.setItem('user', JSON.stringify(updatedUser));
        localStorage.setItem(`onboarding_${currentUser.email}`, 'completed');
        setOnboardingCompleted(true);
        setIsNewUser(false);
        
        // Refresh leaderboard
        await loadLeaderboard();
        
        return true;
      }
      
      return false;
    } catch (error) {
      console.error('Onboarding error:', error);
      return false;
    }
  };

  // Update avatar specifically
  const updateAvatar = async (avatarData) => {
    if (!currentUser) return false;
    
    try {
      const response = await userApi.updateProfile(currentUser._id, avatarData);
      
      if (response.success) {
        const updatedUser = response.user;
        setCurrentUser(updatedUser);
        localStorage.setItem('user', JSON.stringify(updatedUser));
        return true;
      }
      
      return false;
    } catch (error) {
      console.error('Avatar update error:', error);
      return false;
    }
  };

  // Logout function
  const logout = () => {
    setCurrentUser(null);
    setOnboardingCompleted(false);
    localStorage.removeItem('user');
  };

  const value = {
    currentUser,
    isNewUser,
    onboardingCompleted,
    login,
    signup,
    logout,
    completeOnboarding,
    updateUserData,
    updateTasks,
    updateStreak,
    updateAvatar,
    getLeaderboard,
    loading,
    allUsers
  };

  return (
    <AuthContext.Provider value={value}>
      {!loading && children}
    </AuthContext.Provider>
  );
};

// Custom hook to use auth context
export const useAuth = () => {
  return useContext(AuthContext);
};

export default AuthContext; 